"""List an agent project's skills the way `rasa train` loads them."""

from pathlib import Path

from rasa.builder.models import BotFiles, SkillInfo, SkillsResponse
from rasa.builder.project_generator.project_utils import (
    is_restricted_path,
    strip_project_folder,
)
from rasa.mantle.skills.catalog import load_skill_catalog_result
from rasa.shared.project_structure import MANTLE_SKILLS_DIR


def list_agent_skills(project_folder: Path) -> SkillsResponse:
    """List every skill folder of the project, with its load error if it fails.

    Skills are loaded by the Mantle skill catalog without bundled default
    skills, so a skill has an `error` exactly when its folder fails
    `rasa train` (`mantle.validation.skill.failed_to_load`). Like the catalog,
    `_`-prefixed folders are skipped.

    Args:
        project_folder: The agent project folder (parent of `skills/`).

    Returns:
        One entry per skill folder with its raw files, sorted
        case-insensitively by name (falling back to id).
    """
    skills_root = project_folder / MANTLE_SKILLS_DIR
    result = load_skill_catalog_result(project_folder)

    skills = [
        SkillInfo(
            id=skill_id,
            name=skill.name,
            description=skill.description,
            path=f"{MANTLE_SKILLS_DIR}/{skill_id}",
            error=None,
            files=_skill_files(project_folder, skills_root / skill_id),
        )
        for skill_id, skill in result.catalog.skills.items()
    ]
    skills.extend(
        SkillInfo(
            id=directory,
            name=None,
            description=None,
            path=f"{MANTLE_SKILLS_DIR}/{directory}",
            error=strip_project_folder(error, project_folder),
            files=_skill_files(project_folder, skills_root / directory),
        )
        for directory, error in result.load_errors
    )
    skills.sort(key=lambda skill: ((skill.name or skill.id).casefold(), skill.id))

    return SkillsResponse(skills=skills)


def _skill_files(project_folder: Path, skill_dir: Path) -> BotFiles:
    """Read every file in *skill_dir* the way `GET /api/files` reads it."""
    files: BotFiles = {}
    for file in sorted(skill_dir.rglob("*")):
        if not file.is_file() or is_restricted_path(project_folder, file):
            continue
        key = file.relative_to(project_folder).as_posix()
        try:
            files[key] = file.read_text(encoding="utf-8")
        except Exception:
            files[key] = None
    return files
